insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('mathl3b_001', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If 2(3x − 4) − 5(x − 2) = 3(x + 6), what is the value of x?', '["−5", "10", "−8", "8"]'::jsonb, 2, null, 'Left side: 6x − 8 − 5x + 10 = x + 2. So x + 2 = 3x + 18, −2x = 16 and x = −8.', 'published', 'import', now()),
('mathl3b_002', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'If (x + 5)/3 = (2x − 1)/5, what is the value of x?', null, null, '["28"]'::jsonb, 'Cross-multiply: 5(x + 5) = 3(2x − 1), so 5x + 25 = 6x − 3 and x = 28.', 'published', 'import', now()),
('mathl3b_003', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'In the equation a(x + 2) = 4x + b, a and b are constants. If the equation has infinitely many solutions, what is the value of b?', '["2", "4", "6", "8"]'::jsonb, 3, null, 'For every x to work, a = 4 and 2a = b, so b = 8.', 'published', 'import', now()),
('mathl3b_004', 'math', 3, 'Algebra', 'Linear functions', null, null, 'The graph of the linear function f passes through (2, −1) and (5, 8). For what value of x does f(x) = 20?', '["7", "9", "21", "8"]'::jsonb, 1, null, 'Slope = 9 ÷ 3 = 3, so f(x) = 3x − 7. 3x − 7 = 20 gives x = 9.', 'published', 'import', now()),
('mathl3b_005', 'math', 3, 'Algebra', 'Linear functions', null, null, 'A line has x-intercept (6, 0) and y-intercept (0, −4). What is its slope?', null, null, '["2/3", ".6666", ".6667", "0.6666", "0.6667"]'::jsonb, 'Slope = (0 − (−4)) ÷ (6 − 0) = 4/6 = 2/3.', 'published', 'import', now()),
('mathl3b_006', 'math', 3, 'Algebra', 'Linear functions', null, null, 'The cost C, in dollars, of producing n chairs is C = 45n + 1,200. Each chair sells for $85. What is the least number of chairs that must be sold for revenue to exceed cost?', '["27", "30", "14", "31"]'::jsonb, 3, null, '85n > 45n + 1,200 gives 40n > 1,200, so n > 30. The least whole number is 31.', 'published', 'import', now()),
('mathl3b_007', 'math', 3, 'Algebra', 'Linear functions', null, null, 'Lines ℓ and m are perpendicular. Line ℓ has equation 4x − 3y = 9. Line m passes through the origin. Which point lies on line m?', '["(4, 3)", "(3, 4)", "(4, −3)", "(−3, −4)"]'::jsonb, 2, null, 'Line ℓ has slope 4/3, so m has slope −3/4 and equation y = −(3/4)x. When x = 4, y = −3.', 'published', 'import', now()),
('mathl3b_008', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '3x − 2y = 12
6x + ky = 7

In the system, k is a constant. For which value of k does the system have no solution?', '["−2", "−4", "4", "2"]'::jsonb, 1, null, 'The lines are parallel when the coefficients are proportional: 6/3 = k/(−2), so k = −4. Since 2(12) ≠ 7, there is no solution.', 'published', 'import', now()),
('mathl3b_009', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '0.5x + 0.2y = 4.5
x − y = 2

What is the value of y?', null, null, '["5"]'::jsonb, 'x = y + 2. Then 0.5(y + 2) + 0.2y = 4.5, so 0.7y + 1 = 4.5, 0.7y = 3.5 and y = 5.', 'published', 'import', now()),
('mathl3b_010', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'A chemist mixes a 10% salt solution with a 40% salt solution to make 30 liters of a 20% solution. How many liters of the 10% solution are used?', '["15", "20", "10", "25"]'::jsonb, 1, null, 'a + b = 30 and 0.10a + 0.40b = 6. Substituting b = 30 − a: 0.10a + 12 − 0.40a = 6, so 0.30a = 6 and a = 20.', 'published', 'import', now()),
('mathl3b_011', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, 'x + y + z = 12
x − y = 2
y = 2z

What is the value of z?', '["3", "4", "6", "2"]'::jsonb, 3, null, 'y = 2z and x = y + 2 = 2z + 2. Then (2z + 2) + 2z + z = 12, so 5z = 10 and z = 2.', 'published', 'import', now()),
('mathl3b_012', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'For which values of x is 3 − 2x < 7 and x + 4 ≤ 9 both true?', '["−2 < x ≤ 5", "−5 < x ≤ 2", "x < −2 or x ≥ 5", "x ≤ 5"]'::jsonb, 0, null, '3 − 2x < 7 gives x > −2. x + 4 ≤ 9 gives x ≤ 5. Both: −2 < x ≤ 5.', 'published', 'import', now()),
('mathl3b_013', 'math', 3, 'Algebra', 'Linear inequalities', null, null, 'A student has scores of 78, 85, and 91 on three tests. What is the least score on a fourth test that will make the average of all four tests at least 86?', null, null, '["90"]'::jsonb, 'The total must be at least 4 × 86 = 344. 344 − (78 + 85 + 91) = 344 − 254 = 90.', 'published', 'import', now()),
('mathl3b_014', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{2} − 4x)/(x^{2} − 16) for x ≠ 4 and x ≠ −4?', '["x/(x − 4)", "(x − 4)/(x + 4)", "−4x/16", "x/(x + 4)"]'::jsonb, 3, null, 'x^{2} − 4x = x(x − 4) and x^{2} − 16 = (x − 4)(x + 4). Cancel (x − 4).', 'published', 'import', now()),
('mathl3b_015', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (2x^{3})^{2} · 3x^{−4}?', '["6x^{2}", "12x^{2}", "12x^{10}", "36x^{2}"]'::jsonb, 1, null, '(2x^{3})^{2} = 4x^{6}. 4x^{6} · 3x^{−4} = 12x^{2}.', 'published', 'import', now()),
('mathl3b_016', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'If x^{2} + 6x + c = (x + k)^{2} for all x, where c and k are constants, what is the value of c?', null, null, '["9"]'::jsonb, '(x + k)^{2} = x^{2} + 2kx + k^{2}. So 2k = 6, k = 3, and c = k^{2} = 9.', 'published', 'import', now()),
('mathl3b_017', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 1/(x − 2) − 1/(x + 2) for x ≠ ±2?', '["4/(x^{2} − 4)", "0", "2x/(x^{2} − 4)", "4/(x − 2)^{2}"]'::jsonb, 0, null, 'Common denominator (x − 2)(x + 2): [(x + 2) − (x − 2)] ÷ (x^{2} − 4) = 4/(x^{2} − 4).', 'published', 'import', now()),
('mathl3b_018', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to x^{2} − 4x − 7 = 0?', '["−2 ± √11", "2 ± √11", "2 ± √3", "4 ± √11"]'::jsonb, 1, null, 'Complete the square: (x − 2)^{2} = 7 + 4 = 11, so x = 2 ± √11.', 'published', 'import', now()),
('mathl3b_019', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'In the equation 2x^{2} + bx + 18 = 0, b is a positive constant. If the equation has exactly one real solution, what is b?', '["36", "12", "6", "9"]'::jsonb, 1, null, 'The discriminant must be 0: b^{2} − 4(2)(18) = 0, so b^{2} = 144 and b = 12.', 'published', 'import', now()),
('mathl3b_020', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If 9^{x} = 27^{x − 1}, what is the value of x?', null, null, '["3"]'::jsonb, 'Write both as powers of 3: 3^{2x} = 3^{3x − 3}, so 2x = 3x − 3 and x = 3.', 'published', 'import', now()),
('mathl3b_021', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'y = x^{2} + 1
y = 2x + k

In the system, k is a constant. For which value of k does the system have exactly one solution?', '["2", "0", "−1", "1"]'::jsonb, 1, null, 'x^{2} + 1 = 2x + k gives x^{2} − 2x + (1 − k) = 0. One solution means 4 − 4(1 − k) = 0, so k = 0.', 'published', 'import', now()),
('mathl3b_022', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If 3/(x − 1) = 6/(x + 2), what is the value of x?', '["−4", "3", "1", "4"]'::jsonb, 3, null, 'Cross-multiply: 3(x + 2) = 6(x − 1), so 3x + 6 = 6x − 6 and x = 4.', 'published', 'import', now()),
('mathl3b_023', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = a(x − 1)(x − 7), where a is a constant. The graph of y = f(x) has its vertex at (4, −18). What is the value of a?', null, null, '["2"]'::jsonb, 'f(4) = a(3)(−3) = −9a = −18, so a = 2.', 'published', 'import', now()),
('mathl3b_024', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'A culture of bacteria triples every 4 hours. It starts with 200 bacteria. Which expression gives the number after t hours?', '["200 · 3^{4t}", "600t/4", "200 · (4/3)^{t}", "200 · 3^{t/4}"]'::jsonb, 3, null, 'The population is multiplied by 3 once every 4 hours, so the exponent is t/4.', 'published', 'import', now()),
('mathl3b_025', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function h is defined by h(x) = 5(0.8)^{x}. Which statement is true?', '["h decreases by 20% each time x increases by 1", "h(0) = 4", "h increases by 80% each time x increases by 1", "h decreases by 0.8 each time x increases by 1"]'::jsonb, 0, null, 'Multiplying by 0.8 keeps 80% of the value, a 20% decrease. h(0) = 5.', 'published', 'import', now()),
('mathl3b_026', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'If g(x) = 2x + 3 and g(f(x)) = 6x − 1, which expression is f(x)?', '["3x + 1", "4x − 4", "6x − 4", "3x − 2"]'::jsonb, 3, null, '2f(x) + 3 = 6x − 1, so 2f(x) = 6x − 4 and f(x) = 3x − 2.', 'published', 'import', now()),
('mathl3b_027', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = x^{2} − 8x + 12 is shifted 3 units up. What is the minimum value of the new function?', '["15", "−1", "−4", "3"]'::jsonb, 1, null, 'The original vertex is at x = 4: y = 16 − 32 + 12 = −4. Shifting up 3 gives −1.', 'published', 'import', now()),
('mathl3b_028', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A train travels 180 miles at 60 mph and then 180 miles at 90 mph. What is its average speed for the whole trip, in miles per hour?', '["72", "80", "75", "70"]'::jsonb, 0, null, 'Time = 3 + 2 = 5 hours for 360 miles, so the average speed is 72 mph.', 'published', 'import', now()),
('mathl3b_029', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A map is drawn at a scale of 1 : 50,000. Two towns are 7.2 centimeters apart on the map. How many kilometers apart are they? (100,000 cm = 1 km)', null, null, '["3.6"]'::jsonb, '7.2 × 50,000 = 360,000 cm = 3.6 km.', 'published', 'import', now()),
('mathl3b_030', 'math', 3, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'If 4 machines produce 360 parts in 3 hours, how many parts do 6 machines produce in 5 hours at the same rate?', '["900", "600", "750", "1,080"]'::jsonb, 0, null, 'Each machine makes 360 ÷ 4 ÷ 3 = 30 parts per hour. 6 × 5 × 30 = 900.', 'published', 'import', now()),
('mathl3b_031', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A store raises a price by 20% and later offers a 20% discount on the new price. The final price is what percent of the original?', '["104%", "96%", "100%", "80%"]'::jsonb, 1, null, '1.2 × 0.8 = 0.96, or 96% of the original.', 'published', 'import', now()),
('mathl3b_032', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'An investment grows from $2,000 to $2,420 in 2 years with the same percent increase each year. What is the yearly percent increase?', null, null, '["10", "10%"]'::jsonb, '2,000(1 + r)^{2} = 2,420, so (1 + r)^{2} = 1.21 and 1 + r = 1.1. The rate is 10%.', 'published', 'import', now()),
('mathl3b_033', 'math', 3, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'In a school, 40% of students play a sport. Of those, 25% play soccer. What percent of all students play soccer?', '["65%", "10%", "15%", "25%"]'::jsonb, 1, null, '0.40 × 0.25 = 0.10, or 10%.', 'published', 'import', now()),
('mathl3b_034', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A data set has 9 values with a median of 50. If the greatest value is increased by 30, which statement must be true?', '["The median and mean both increase", "The range decreases", "The median stays 50 and the mean increases", "The mean stays the same and the median increases"]'::jsonb, 2, null, 'Changing the greatest value doesn''t change the middle value, but it raises the total and therefore the mean.', 'published', 'import', now()),
('mathl3b_035', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Class A''s test scores have a mean of 80 and a standard deviation of 4. Class B''s have a mean of 80 and a standard deviation of 12. Which statement is best supported?', '["Class B''s scores are more spread out than Class A''s", "Class A has more students", "Both classes have identical scores", "Class B scored higher on average"]'::jsonb, 0, null, 'The means are equal; the larger standard deviation means Class B''s scores vary more.', 'published', 'import', now()),
('mathl3b_036', 'math', 3, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The mean of 8 numbers is 15. When two numbers are removed, the mean of the remaining 6 is 14. What is the sum of the two numbers removed?', '["34", "42", "36", "30"]'::jsonb, 2, null, '8 × 15 = 120 and 6 × 14 = 84. 120 − 84 = 36.', 'published', 'import', now()),
('mathl3b_037', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'A scatterplot of data has a line of best fit y = 0.75x + 12. One data point is (40, 38). What is the residual for this point (actual minus predicted)?', null, null, '["-4", "−4"]'::jsonb, 'Predicted: 0.75(40) + 12 = 42. Residual = 38 − 42 = −4.', 'published', 'import', now()),
('mathl3b_038', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'A population model is P(t) = 5,000(1.02)^{t}, where t is years after 2020. Which is the best interpretation of 1.02?', '["The population doubles every 2 years", "The population in 2020 was 1.02 thousand", "The population grows by 2% each year", "The population grows by 102 people each year"]'::jsonb, 2, null, 'Multiplying by 1.02 each year means a 2% yearly increase.', 'published', 'import', now()),
('mathl3b_039', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, '{"h": ["", "Has condition", "No condition"], "r": [["Tests positive", "30", "50"], ["Tests negative", "10", "410"]]}'::jsonb, 'The table shows results of a test for a condition among 500 people.

If a person tests positive, what is the probability the person actually has the condition?', '["3/4", "3/50", "3/8", "15/38"]'::jsonb, 2, null, 'There are 30 + 50 = 80 positive tests, and 30 of those people have the condition: 30/80 = 3/8.', 'published', 'import', now()),
('mathl3b_040', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A fair coin is tossed 3 times. What is the probability of getting exactly 2 heads?', '["3/8", "1/2", "2/3", "1/4"]'::jsonb, 0, null, 'There are 8 outcomes, and 3 have exactly two heads (HHT, HTH, THH).', 'published', 'import', now()),
('mathl3b_041', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A study reports that a random sample of 400 voters had mean age 46 with a margin of error of 1.5 years. A second random sample of 1,600 voters is taken in the same way. Its margin of error would most likely be', '["exactly 1.5 years", "exactly 6 years", "smaller than 1.5 years", "larger than 1.5 years"]'::jsonb, 2, null, 'Larger random samples produce smaller margins of error.', 'published', 'import', now()),
('mathl3b_042', 'math', 3, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'Researchers surveyed 1,000 randomly selected adults in Ohio and found that 62% support a new park tax. To which group can the result be generalized?', '["Only the 1,000 people surveyed", "All adults in the United States", "Adults in Ohio", "Children in Ohio"]'::jsonb, 2, null, 'A random sample represents the population it was drawn from: adults in Ohio.', 'published', 'import', now()),
('mathl3b_043', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'The circle x^{2} + y^{2} + 10x − 4y + 13 = 0 has center (h, k). What is h + k?', '["3", "7", "−7", "−3"]'::jsonb, 3, null, 'Complete the square: (x + 5)^{2} + (y − 2)^{2} = 16. The center is (−5, 2), so h + k = −3.', 'published', 'import', now()),
('mathl3b_044', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has a radius of 10. A chord is 12 units long. How far is the chord from the center?', null, null, '["8"]'::jsonb, 'The perpendicular from the center bisects the chord, forming a right triangle with legs 6 and d and hypotenuse 10. d = √(100 − 36) = 8.', 'published', 'import', now()),
('mathl3b_045', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'An arc of a circle with radius 12 has length 8π. What is the measure, in degrees, of its central angle?', '["120", "60", "150", "90"]'::jsonb, 0, null, 'The circumference is 24π. 8π ÷ 24π = 1/3, and 1/3 of 360° is 120°.', 'published', 'import', now()),
('mathl3b_046', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle ABC, angle C is 90° and sin A = 7/25. What is cos B?', '["24/25", "7/24", "7/25", "25/7"]'::jsonb, 2, null, 'Angles A and B are complementary, so cos B = sin A = 7/25.', 'published', 'import', now()),
('mathl3b_047', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A 20-foot ladder makes a 60° angle with the ground. How high up the wall does it reach?', '["20√3 feet", "10√2 feet", "10 feet", "10√3 feet"]'::jsonb, 3, null, 'Height = 20 sin 60° = 20(√3/2) = 10√3.', 'published', 'import', now()),
('mathl3b_048', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'What is the value of 3π/4 radians in degrees?', null, null, '["135"]'::jsonb, 'Multiply by 180/π: (3π/4)(180/π) = 135.', 'published', 'import', now()),
('mathl3b_049', 'math', 3, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In triangle ABC, AB = 12 and AC = 18. The bisector of angle A meets BC at D, and BD = 8. What is DC?', '["12", "16", "13.5", "10"]'::jsonb, 0, null, 'The angle bisector divides the opposite side in the ratio of the other two sides: BD/DC = 12/18, so DC = 8 × 18 ÷ 12 = 12.', 'published', 'import', now()),
('mathl3b_050', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cube''s surface area is 150 square inches. What is its volume, in cubic inches?', '["150", "216", "125", "25"]'::jsonb, 2, null, 'Each face has area 150 ÷ 6 = 25, so an edge is 5 and the volume is 125.', 'published', 'import', now()),
('mathl3b_051', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'Two similar triangles have corresponding sides in the ratio 2 : 5. The smaller triangle''s area is 12. What is the larger triangle''s area?', '["75", "150", "30", "60"]'::jsonb, 0, null, 'Areas scale by the square of the ratio: 12 × (5/2)^{2} = 12 × 6.25 = 75.', 'published', 'import', now()),
('mathl3b_052', 'math', 3, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cylinder has volume 72π and height 8. What is its radius?', null, null, '["3"]'::jsonb, 'πr^{2}(8) = 72π gives r^{2} = 9, so r = 3.', 'published', 'import', now()),
('rwl3b_001', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The results of the early trial were ____: patients taking the drug improved slightly more than those taking a placebo, but the difference was small enough that it could have arisen by chance.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["equivocal", "fabricated", "unambiguous", "irrelevant"]'::jsonb, 0, null, 'Results that can be read two ways are equivocal.', 'published', 'import', now()),
('rwl3b_002', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Many archaeologists now argue that a series of severe droughts in the ninth century ____ the abandonment of several large Maya cities, as failing harvests made it impossible to feed dense urban populations.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["concealed", "postponed", "precipitated", "prevented"]'::jsonb, 2, null, 'The drought brought about the collapse, which is what precipitated means.', 'published', 'import', now()),
('rwl3b_003', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Rather than presenting the general as either a hero or a villain, the biography offers a ____ portrait, acknowledging his tactical brilliance while also examining the costly mistakes that followed from his stubbornness.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["simplistic", "nuanced", "hostile", "outdated"]'::jsonb, 1, null, 'A portrayal that shows a character''s mixed qualities is nuanced.', 'published', 'import', now()),
('rwl3b_004', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Archaeologist Sarah Parcak notes that some of the most revealing finds are not gold masks but ____ objects such as cooking pots and broken tools, which show how ordinary people actually lived.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["extraordinary", "secret", "dangerous", "mundane"]'::jsonb, 3, null, 'Ordinary, everyday objects are mundane.', 'published', 'import', now()),
('rwl3b_005', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Cosmologists have struggled to ____ two measurements of how fast the universe is expanding: one based on the oldest light in the cosmos and another based on nearby exploding stars, which yield noticeably different values.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["exaggerate", "replicate", "dismiss", "reconcile"]'::jsonb, 3, null, 'Bringing two conflicting sets of data into agreement is what reconcile means.', 'published', 'import', now()),
('rwl3b_006', 'rw', 3, 'Craft and Structure', 'Words in Context', 'The committee gave the proposal only qualified support, approving the first phase of construction while insisting that the remaining phases wait for an independent environmental review.', null, 'As used in the text, what does the word "qualified" most nearly mean?', '["eligible", "certified", "limited", "skilled"]'::jsonb, 2, null, 'The approval came with conditions, so "qualified" means limited or restricted.', 'published', 'import', now()),
('rwl3b_007', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Fairy shrimp live in ____ pools that form after spring rains and dry up within weeks. To survive, the shrimp lay eggs that can remain dormant in dry mud for years until the next rains arrive.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["predictable", "ephemeral", "massive", "permanent"]'::jsonb, 1, null, 'Ponds that last only a few weeks are short-lived, or ephemeral.', 'published', 'import', now()),
('rwl3b_008', 'rw', 3, 'Craft and Structure', 'Words in Context', 'To reconstruct the climate of medieval Europe, historians combined evidence from ____ sources, including tree rings, monastery harvest records, ice cores, and the dates on which local rivers froze.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["obscure", "redundant", "identical", "disparate"]'::jsonb, 3, null, 'Very different sources are disparate.', 'published', 'import', now()),
('rwl3b_009', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Many birds suddenly fall silent just before a total solar eclipse. The usual explanation is that the sudden darkness tricks them into behaving as if night has come. Yet recordings made during a 2024 eclipse found that some species began their dawn songs as the light returned, while others stayed silent long after. The response, it seems, varies more than the simple explanation suggests.', null, 'Which choice best describes the function of the second sentence in the overall structure of the text?', '["It presents a common explanation that the rest of the text challenges", "It states the author''s own conclusion", "It defines a technical term", "It provides data that support the first sentence"]'::jsonb, 0, null, 'The second sentence gives the usual explanation (fear), which the third and fourth sentences complicate.', 'published', 'import', now()),
('rwl3b_010', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'For more than a century, histories of the first transcontinental railroad focused on the companies'' owners and engineers, saying little about the thousands of Chinese immigrants who did much of the dangerous work in the Sierra Nevada. In recent years, a project at Stanford University has gathered payroll records, letters, and archaeological finds to reconstruct these workers'' lives and labor.', null, 'Which choice best states the main purpose of the text?', '["To describe the history of a single family", "To show how an overlooked group''s contributions are being recognized through new research", "To argue that census records are unreliable", "To explain how railroads were constructed"]'::jsonb, 1, null, 'The text explains that historians are using new records to document Chinese workers'' role in building the railroad.', 'published', 'import', now()),
('rwl3b_011', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Ecologists hypothesized that adding wolves'' scent to a forest would keep deer away from young trees. To test this, they sprayed wolf urine near half of their study plots. Deer visited the sprayed plots less often during the first month, but by the third month, deer were browsing both kinds of plots equally.', null, 'Which choice best describes the overall structure of the text?', '["It states a hypothesis, describes a test of it, and reports a result that only partly supports it", "It describes two events and argues they are unrelated", "It lists the achievements of a scientist", "It presents a problem and several possible solutions"]'::jsonb, 0, null, 'The text gives a hypothesis, the experiment, and a mixed result.', 'published', 'import', now()),
('rwl3b_012', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Remote work has transformed many offices. To be sure, some employees miss the casual conversations of a shared workplace, and managers worry about training new hires. But surveys consistently show that most remote workers report higher job satisfaction and fewer hours lost to commuting.', null, 'Which choice best describes the function of the phrase "to be sure" in the text?', '["It signals that the author is completely certain", "It introduces a new piece of evidence for the main claim", "It marks the conclusion of the argument", "It introduces a concession before the author returns to the main argument"]'::jsonb, 3, null, '"To be sure" acknowledges a point on the other side before the author''s "but" returns to the argument.', 'published', 'import', now()),
('rwl3b_013', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
A review of health studies concluded that coffee drinkers live longer than people who avoid coffee, leading the authors to claim that coffee protects health.

Text 2
Researchers who examined the same data in more detail found that the benefits appeared only among people who drank two to four cups a day. Among heavy drinkers, some health risks increased. The relationship, they argue, is not as simple as "more coffee is better."', null, 'Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?', '["By arguing that the study in Text 1 was faked", "By claiming that coffee has no effect on health", "By agreeing that coffee is harmful in every amount", "By suggesting that the claim is premature because the effect may depend on how much coffee people drink"]'::jsonb, 3, null, 'Text 2 reports benefits at moderate levels and risks at high levels, so it would say Text 1''s broad claim is too simple.', 'published', 'import', now()),
('rwl3b_014', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
In laboratory tests, dolphins seemed only moderately skilled at cooperating. But researchers watching wild dolphins in Brazil observed them working with local fishers, driving fish toward nets and signaling when to cast.

Text 2
Captive crows rarely showed much skill at long-term planning. In the wild, however, scientists documented crows hiding food in dozens of locations and returning to each one months later.', null, 'Which choice best describes a point on which the authors of both texts would most likely agree?', '["Laboratory experiments are never useful", "Studying animal behavior in the wild can reveal abilities that laboratory studies miss", "Animals in the wild rarely use tools", "Crows are more intelligent than dolphins"]'::jsonb, 1, null, 'Both texts describe abilities observed only when animals were studied in natural settings.', 'published', 'import', now()),
('rwl3b_015', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Rocks brought back by Apollo astronauts revealed something surprising: the Moon''s surface has nearly the same oxygen isotope ratios as Earth''s rocks. Because these ratios differ widely across the solar system, the similarity suggests that Earth and the Moon share an origin. Many planetary scientists now favor the idea that a Mars-sized body struck the young Earth, and debris from the collision gathered into the Moon.', null, 'Which choice best states the main idea of the text?', '["Recent evidence suggests that the Moon may have formed from material ejected by a giant collision with the early Earth", "The Moon has always orbited Earth at the same distance", "Apollo astronauts discovered water on the Moon", "Earth and the Moon formed separately in different parts of the solar system"]'::jsonb, 0, null, 'The text explains how matching rock chemistry supports the giant-impact explanation.', 'published', 'import', now()),
('rwl3b_016', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'In parts of Mozambique, Yao honey hunters work with a wild bird called the greater honeyguide, which leads them to bees'' nests; the hunters then share the wax with the bird. Biologist Claire Spottiswoode found that the birds were more than twice as likely to guide people who made the hunters'' traditional "brrr-hm" call than people who made other sounds, suggesting that the birds recognize the call as a request for help.', null, 'According to the text, what did the researchers find surprising about the honeyguide bird?', '["It avoids contact with humans", "It responds to a specific call that people use to request its help", "It cannot fly long distances", "It eats only honey"]'::jsonb, 1, null, 'The text says honeyguides were more likely to lead people who used the traditional "brrr-hm" call.', 'published', 'import', now()),
('rwl3b_017', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'The following text is adapted from a short story.

The acceptance letter had arrived that morning, and Amara had read it so many times the paper had gone soft. Medical school, four hundred miles away. Her mother had cried and then laughed and then cried again. But at dinner, watching her younger brothers argue over the last roti, Amara found that she could not bring herself to speak. She knew that once she left, every visit home would make her a little more of a guest.', null, 'Based on the text, what is the main reason the narrator hesitates?', '["She is unsure whether she wants to be a doctor", "She has been told she failed the exam", "She fears that her success will distance her from her family", "She does not have enough money for the journey"]'::jsonb, 2, null, 'She is proud of the acceptance but worries about how it will change her place in her family.', 'published', 'import', now()),
('rwl3b_018', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'Researchers concluded that growing up bilingual improves children''s ability to switch between tasks but does not affect short-term memory.', '{"h": ["Group", "Task-switching accuracy (%)", "Memory task accuracy (%)"], "r": [["Bilingual", "88", "75"], ["Monolingual", "79", "74"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the researchers'' conclusion?', '["Both groups completed two tasks", "Bilingual children scored 88 percent on the switching task", "In bilingual children, accuracy on the switching task was 88 percent, compared with 79 percent in monolingual children, while both groups scored about the same on the memory task", "Monolingual children scored 74 percent on the memory task"]'::jsonb, 2, null, 'The conclusion is that bilingualism helps with switching specifically, so the evidence must show a gap on switching but not on memory.', 'published', 'import', now()),
('rwl3b_019', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A historian argues that Abraham Lincoln''s views on slavery were reshaped by his 1858 debates with Stephen Douglas, claiming that the arguments he developed in response to Douglas led him to positions he had not held before.', null, 'Which finding, if true, would most directly undermine the historian''s argument?', '["Letters written by Lincoln before the debates show that he already held the views he expressed in them", "Newspapers printed the full text of the debates", "Thousands of people attended the debates", "Douglas won the Senate race in 1858"]'::jsonb, 0, null, 'The argument is that the debates changed Lincoln''s views; evidence that he held them beforehand undermines it.', 'published', 'import', now()),
('rwl3b_020', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'In an essay, the author describes developing a deep, almost expert understanding of the natural world through close observation in childhood.', null, 'Which quotation from the essay most effectively illustrates the claim?', '["\"In winter, the river sometimes froze at its edges.\"", "\"I learned to read the river as other children read books: the color of the water told me its depth, and the ripples told me where rocks lay hidden.\"", "\"The river was wider than any I have seen since.\"", "\"My father owned a small boat with a green hull.\""]'::jsonb, 1, null, 'The claim is about close, expert observation of nature; only this quotation shows the writer interpreting signs in the water.', 'published', 'import', now()),
('rwl3b_021', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A student claims that over two decades, wind power grew substantially in the country''s electricity mix while coal declined.', '{"h": ["Source", "Share in 2000 (%)", "Share in 2020 (%)"], "r": [["Coal", "52", "19"], ["Wind", "0.1", "8.4"]]}'::jsonb, 'Which choice best describes data from the table that support the student''s claim?', '["Wind produced 8.4 percent of electricity in 2020", "Coal produced 52 percent of electricity in 2000", "Between 2000 and 2020, the share of electricity from wind rose from 0.1 percent to 8.4 percent, while the share from coal fell from 52 percent to 19 percent", "Electricity use increased slightly over the period"]'::jsonb, 2, null, 'The claim is that wind grew while coal declined, so both trends are needed.', 'published', 'import', now()),
('rwl3b_022', 'rw', 3, 'Information and Ideas', 'Inferences', 'Marine biologists exposed two groups of shrimp to gradually warming water. In the first tank, which also had low oxygen, most shrimp died once the water reached 28°C. In the second, well-oxygenated tank, most shrimp survived until 32°C. This suggests that ____', null, 'Which choice most logically completes the text?', '["the shrimp''s ability to survive may depend on factors besides the temperature of the water", "warming has no effect on any species", "the shrimp prefer warm water to cold water", "the shrimp have adapted to all conditions"]'::jsonb, 0, null, 'Shrimp died at different temperatures in the two tanks, so temperature alone can''t explain survival.', 'published', 'import', now()),
('rwl3b_023', 'rw', 3, 'Information and Ideas', 'Inferences', 'Astronomers studying a cluster of several hundred stars found that nearly all of them have the same chemical composition and appear to be roughly the same age. Since stars that form from the same cloud of gas share its chemistry, the astronomers concluded that ____', null, 'Which choice most logically completes the text?', '["the stars are moving apart rapidly", "all star clusters are the same age", "the cluster contains no young stars", "the stars in the cluster likely formed at about the same time"]'::jsonb, 3, null, 'Stars with similar ages and composition probably formed together.', 'published', 'import', now()),
('rwl3b_024', 'rw', 3, 'Information and Ideas', 'Inferences', 'Reviews of the 1872 premiere of a symphony describe a fourth movement featuring a long solo for horn. The only surviving manuscript of the symphony, however, has no horn solo, and its paper and ink date from the late 1870s. These details suggest that ____', null, 'Which choice most logically completes the text?', '["the symphony was never performed", "the orchestra played the music incorrectly", "the program printed the wrong title", "the composer may have revised the symphony after its first performance"]'::jsonb, 3, null, 'The surviving score differs from what was reported at the premiere, suggesting later revisions.', 'published', 'import', now()),
('rwl3b_025', 'rw', 3, 'Information and Ideas', 'Inferences', 'Researchers compared wheat plants that carried a particular gene with plants that lacked it. In well-watered fields, the two groups produced similar harvests. In fields that received half the usual rainfall, however, plants with the gene produced about 30 percent more grain. These results suggest that ____', null, 'Which choice most logically completes the text?', '["the plants do not need water", "the gene may help the plants cope with drought", "the gene causes plants to grow more slowly in all conditions", "drought has no effect on the plants"]'::jsonb, 1, null, 'Plants with the gene did better only under dry conditions.', 'published', 'import', now()),
('rwl3b_026', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Fire is essential to the life cycle of giant ____ cones open and release seeds only after being heated by the flames.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["sequoias their", "sequoias, and, their", "sequoias; their", "sequoias, their"]'::jsonb, 2, null, 'Two complete sentences are joined with a semicolon; a comma alone would be a comma splice.', 'published', 'import', now()),
('rwl3b_027', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Historians point to two forces that transformed the American ____ the expansion of the railroads and the rise of large factories.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["economy:", "economy", "economy;", "economy,"]'::jsonb, 0, null, 'A colon introduces the explanation (the two causes) after a complete sentence.', 'published', 'import', now()),
('rwl3b_028', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Several of the languages spoken in the region—Quechua, Aymara, and ____ are recognized as official languages of Bolivia.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Spanish,", "Spanish;", "Spanish—", "Spanish"]'::jsonb, 2, null, 'The interrupting list began with a dash, so it must end with a dash.', 'published', 'import', now()),
('rwl3b_029', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Astronomers used the Atacama Large Millimeter/submillimeter ____ network of 66 radio antennas in Chile, to photograph the dusty disks around young stars.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Array; a", "Array a", "Array, a", "Array. A"]'::jsonb, 2, null, 'The phrase "a network of 66 radio antennas in Chile" describes the Array and is set off with commas.', 'published', 'import', now()),
('rwl3b_030', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The survey of reef fish revealed ____ several species once thought to be rare are actually common at night.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["that,", "that;", "that:", "that"]'::jsonb, 3, null, 'No punctuation belongs between "that" and the clause it introduces.', 'published', 'import', now()),
('rwl3b_031', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'Dorothy Vaughan taught herself the programming language FORTRAN in the early ____ she then trained the women in her group so they could work with NASA''s new electronic computers.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1960s; and", "1960s. And,", "1960s and", "1960s, and"]'::jsonb, 3, null, 'A comma comes before "and" when it joins two complete sentences.', 'published', 'import', now()),
('rwl3b_032', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'One of the oldest known maps of the world, carved on a clay tablet in ancient Babylon, ____ survived for more than 2,500 years.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are", "has", "have", "were"]'::jsonb, 1, null, 'The subject is "one," which is singular.', 'published', 'import', now()),
('rwl3b_033', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', '____ thousands of hours of recordings, the team concluded that sperm whales use distinct patterns of clicks to identify members of their family groups.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["To have analyzed", "Having analyzed", "Analyzed", "Being analyzed"]'::jsonb, 1, null, '"Having analyzed" correctly shows that the team finished the analysis before reaching its conclusion.', 'published', 'import', now()),
('rwl3b_034', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'After deliberating for three days, the jury delivered ____ verdict late Friday afternoon.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it''s", "they''re", "its", "their"]'::jsonb, 2, null, 'The pronoun refers to "the jury," acting as a single unit.', 'published', 'import', now()),
('rwl3b_035', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Either the lead researcher or the assistants ____ responsible for labeling each sample before storage.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "is", "has been", "was"]'::jsonb, 0, null, 'In "either…or," the verb agrees with the nearer subject, "the assistants" (plural).', 'published', 'import', now()),
('rwl3b_036', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'If the expedition had left base camp a day earlier, it ____ at the summit before the storm.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["arrives", "would have arrived", "had arrived", "will arrive"]'::jsonb, 1, null, 'In a past unreal conditional ("If…had left"), the result clause uses "would have."', 'published', 'import', now()),
('rwl3b_037', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'The prize was shared by three physicists, among ____ was the first woman to win it in more than sixty years.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["whose", "which", "whom", "who"]'::jsonb, 2, null, 'The pronoun is the object of "among," so "whom" is correct.', 'published', 'import', now()),
('rwl3b_038', 'rw', 3, 'Expression of Ideas', 'Transitions', 'In the 1860s, economist William Stanley Jevons observed that as steam engines became more efficient, using less coal for the same work, Britain''s total coal consumption did not fall. ____ it rose, because cheaper power made steam engines worth using in many new industries.', null, 'Which choice completes the text with the most logical transition?', '["Ironically,", "For instance,", "Accordingly,", "Similarly,"]'::jsonb, 0, null, 'It is unexpected that efficiency led to more coal use, so "Ironically" fits.', 'published', 'import', now()),
('rwl3b_039', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Sea turtles appear to use Earth''s magnetic field to find the beaches where they hatched. ____ some salmon seem to rely on magnetic cues to locate the river mouths they left years earlier.', null, 'Which choice completes the text with the most logical transition?', '["Conversely,", "Instead,", "Likewise,", "Nonetheless,"]'::jsonb, 2, null, 'Both sentences describe animals using the Earth''s magnetic field, so "Likewise" fits.', 'published', 'import', now()),
('rwl3b_040', 'rw', 3, 'Expression of Ideas', 'Transitions', 'When engineers proposed building the Panama Canal with a system of locks rather than at sea level, many critics argued that the locks would be too large to operate reliably. ____ the canal opened in 1914 and has operated with locks ever since.', null, 'Which choice completes the text with the most logical transition?', '["Similarly,", "Nevertheless,", "Therefore,", "Specifically,"]'::jsonb, 1, null, 'The success came despite doubts, so a contrast transition fits.', 'published', 'import', now()),
('rwl3b_041', 'rw', 3, 'Expression of Ideas', 'Transitions', 'Unlike the planets, comets follow long, stretched orbits that carry them far from the Sun. As a comet approaches the Sun, heat turns its ice into gas. ____ comets develop their glowing tails only when they are relatively close to the Sun.', null, 'Which choice completes the text with the most logical transition?', '["Hence,", "However,", "Meanwhile,", "For example,"]'::jsonb, 0, null, 'The last sentence states a conclusion that follows from the first two.', 'published', 'import', now()),
('rwl3b_042', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The new library building collects rainwater for its toilets, uses solar panels for most of its electricity, and was built largely from recycled steel. ____ it was designed to have as small an environmental footprint as possible.', null, 'Which choice completes the text with the most logical transition?', '["Even so,", "In contrast,", "Previously,", "In short,"]'::jsonb, 3, null, 'The final sentence sums up the details before it.', 'published', 'import', now()),
('rwl3b_043', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Shirley Chisholm was born in Brooklyn, New York, in 1924.
• In 1968, she became the first Black woman elected to Congress.
• In 1972, she ran for president.
• She was the first Black candidate to seek a major party''s presidential nomination.
• She was also the first woman to run for the Democratic nomination.
• Her slogan was "Unbought and Unbossed."', null, 'The student wants to explain why Shirley Chisholm''s 1972 campaign was historically significant. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In 1972, Shirley Chisholm became the first Black candidate to seek a major party''s nomination for president and the first woman to run for the Democratic nomination.", "Shirley Chisholm was born in Brooklyn in 1924.", "Shirley Chisholm''s campaign slogan was \"Unbought and Unbossed.\"", "Shirley Chisholm served in the U.S. House of Representatives."]'::jsonb, 0, null, 'Only this choice explains what made the campaign historic.', 'published', 'import', now()),
('rwl3b_044', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Hubble Space Telescope launched in 1990.
• It mainly observes visible and ultraviolet light.
• The James Webb Space Telescope launched in 2021.
• It observes infrared light.
• Infrared light passes through dust clouds that block visible light.', null, 'The student wants to emphasize a difference between the two telescopes. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While Hubble mainly observes visible and ultraviolet light, the James Webb Space Telescope observes infrared light, letting it see through dust that blocks Hubble''s view.", "Both Hubble and Webb are space telescopes.", "Hubble was launched in 1990.", "The James Webb Space Telescope was launched in 2021."]'::jsonb, 0, null, 'Only this choice states a difference in what the telescopes observe and why it matters.', 'published', 'import', now()),
('rwl3b_045', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Researchers wanted to know whether city noise affects children''s sleep.
• They studied 400 children in three cities.
• Children wore devices that tracked their sleep.
• Noise was measured outside each home.
• Children in louder neighborhoods slept 25 fewer minutes a night on average.', null, 'The student wants to present the research question and the answer the study found. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Noise levels were measured outside each home.", "Children wore devices that measured sleep.", "Researchers studied 400 children in three cities.", "Asking whether city noise affects how well children sleep, researchers found that children in louder neighborhoods slept an average of 25 fewer minutes per night."]'::jsonb, 3, null, 'Only this choice states both the question and the finding.', 'published', 'import', now()),
('rwl1c_001', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Owls are ____ hunters. They sleep during the day and fly out after dark to catch mice and other small animals.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["nocturnal", "noisy", "sleepy", "colorful"]'::jsonb, 0, null, 'Animals that are active at night are nocturnal.', 'published', 'import', now()),
('rwl1c_002', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Mr. Okafor was known throughout the neighborhood as a ____ man. Each summer, he gave away most of the vegetables from his garden to families who needed them.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["nervous", "selfish", "generous", "forgetful"]'::jsonb, 2, null, 'Giving away most of what you have to help others is generous.', 'published', 'import', now()),
('rwl1c_003', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Stonehenge, the ring of giant stones in England, is ____. Parts of it were built more than 4,500 years ago.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["modern", "tiny", "temporary", "ancient"]'::jsonb, 3, null, 'Something more than 4,000 years old is ancient.', 'published', 'import', now()),
('rwl1c_004', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The ____ winds of the hurricane knocked down trees and power lines across the coastal town.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["weak", "fierce", "quiet", "gentle"]'::jsonb, 1, null, 'Winds strong enough to knock down trees and power lines are fierce.', 'published', 'import', now()),
('rwl1c_005', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Young Thomas Edison was so ____ that he asked his teachers endless questions about how things worked.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["curious", "angry", "tired", "bored"]'::jsonb, 0, null, 'Asking many questions and wanting to learn shows someone is curious.', 'published', 'import', now()),
('rwl1c_006', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The forecast called for fair weather all weekend, so the family packed a picnic and headed to the lake.', null, 'As used in the text, what does the word "fair" most nearly mean?', '["clear and sunny", "just", "carnival", "light-colored"]'::jsonb, 0, null, 'The text is about the weather, so "fair" means clear and sunny.', 'published', 'import', now()),
('rwl1c_007', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The ____ lilacs filled the whole garden with their sweet smell.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["bitter", "invisible", "fragrant", "silent"]'::jsonb, 2, null, 'Flowers with a sweet smell that fills the garden are fragrant.', 'published', 'import', now()),
('rwl1c_008', 'rw', 1, 'Craft and Structure', 'Words in Context', 'After the storm, workers climbed onto the school''s roof to ____ the damage so that rain would no longer leak into the classrooms.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["sell", "destroy", "paint", "repair"]'::jsonb, 3, null, 'Fixing the broken roof is what repair means.', 'published', 'import', now()),
('rwl1c_009', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'Penguins have several ways of staying warm in icy waters. A thick layer of fat under their skin traps heat, and tightly packed feathers keep out cold water. Emperor penguins also huddle together in large groups during the coldest storms.', null, 'Which choice best states the main purpose of the text?', '["To compare penguins with polar bears", "To explain how penguins stay warm in cold places", "To describe how penguins find food", "To argue that penguins should live in zoos"]'::jsonb, 1, null, 'The text describes the features that keep penguins warm.', 'published', 'import', now()),
('rwl1c_010', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'On July 20, 1969, astronauts Neil Armstrong and Buzz Aldrin landed on the Moon. Armstrong was the first to step onto its surface. The landing showed that people could travel to another world and return safely to Earth.', null, 'Which choice best describes the function of the last sentence in the overall structure of the text?', '["It asks a question for the reader", "It describes what happened first", "It explains why the event described earlier was important", "It disagrees with the first sentence"]'::jsonb, 2, null, 'The last sentence explains the importance of the moon landing.', 'published', 'import', now()),
('rwl1c_011', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'Every fall, the school''s gardening club planted tulip bulbs, and every winter, squirrels dug them up and ate them. This year, the club placed wire cages over the bulbs before covering them with soil. In the spring, nearly all of the tulips bloomed.', null, 'Which choice best describes the overall structure of the text?', '["It describes a problem and then explains how it was solved", "It lists facts about a city in order of size", "It tells two unrelated stories", "It argues for one side of a debate"]'::jsonb, 0, null, 'The text describes squirrels eating the bulbs (problem) and the wire cages (solution).', 'published', 'import', now()),
('rwl1c_012', 'rw', 1, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
E-books are easy to carry and can hold hundreds of titles on a single device, making reading convenient anywhere.

Text 2
E-books are handy, but some studies have found that readers remember details from a story better when they read it in a printed book.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By claiming that screens are always better than books", "By saying that no one reads e-books", "By agreeing that reading on screens is convenient but suggesting printed books help readers remember more", "By arguing that people should stop reading"]'::jsonb, 2, null, 'Text 2 grants convenience but adds that print may help memory.', 'published', 'import', now()),
('rwl1c_013', 'rw', 1, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Learning to play a musical instrument teaches patience, since students must practice the same passages many times.

Text 2
Students who play in a band or orchestra learn to listen carefully to others and work together as a team.', null, 'Which choice best describes how the two texts are related?', '["Text 2 argues against the activity in Text 1", "The texts describe two different sports", "Text 1 is about history and Text 2 is about science", "Both texts describe benefits of the same activity"]'::jsonb, 3, null, 'Both texts describe benefits of learning a musical instrument.', 'published', 'import', now()),
('rwl1c_014', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Sloths spend almost their entire lives hanging in rainforest trees. Their long, curved claws let them grip branches easily, even while sleeping. Their slow movements save energy, and green algae growing in their fur help them blend in with the leaves.', null, 'Which choice best states the main idea of the text?', '["Sloths eat mostly insects", "Sloths spend most of their time on the ground", "Sloths are the fastest animals in the rainforest", "Sloths have several features that help them live in trees"]'::jsonb, 3, null, 'The text describes the sloth''s claws, slow movement, and algae-covered fur, all suited to life in trees.', 'published', 'import', now()),
('rwl1c_015', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'In 1960, six-year-old Ruby Bridges became the first African American student to attend William Frantz Elementary School in New Orleans, which had been all white. Because angry crowds gathered outside to protest, federal marshals walked with her to and from school each day.', null, 'According to the text, why did Ruby Bridges need federal marshals to walk with her to school?', '["Because she lived far from the school", "Because the school was closed", "Because some people were angry that she was attending an all-white school", "Because she was a famous athlete"]'::jsonb, 2, null, 'The text says crowds protested her attending the formerly all-white school.', 'published', 'import', now()),
('rwl1c_016', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Every winter, tens of thousands of volunteers across North America take part in the Christmas Bird Count. They record every bird they see in a set area on a single day. Scientists use the counts, which began in 1900, to track how bird populations change over time.', null, 'Which choice best states the main idea of the text?', '["Counting birds is a new hobby", "Scientists do not need help studying birds", "Volunteers help scientists by counting birds", "Birds are disappearing from all parks"]'::jsonb, 2, null, 'The text describes how volunteer bird counts provide useful data to scientists.', 'published', 'import', now()),
('rwl1c_017', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Leo had trained for the race all summer. When he crossed the finish line in second place, he grinned, lifted his trophy over his head, and waved to his family in the stands.', null, 'Based on the text, how does Leo feel at the end?', '["Proud", "Scared", "Confused", "Bored"]'::jsonb, 0, null, 'Leo grins and holds the trophy over his head after finishing the race, showing pride.', 'published', 'import', now()),
('rwl1c_018', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A class surveyed students about their favorite fruit. The results show that ____.', '{"h": ["Fruit", "Students"], "r": [["Apples", "34"], ["Bananas", "21"], ["Grapes", "18"], ["Oranges", "12"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the statement?', '["equal numbers of students chose each fruit", "no students chose grapes", "more students chose apples than any other fruit", "bananas were the most popular fruit"]'::jsonb, 2, null, 'Apples have 34 votes, more than any other fruit listed.', 'published', 'import', now()),
('rwl1c_019', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A city official claims that building a new playground increased the number of people using the park.', null, 'Which finding would best support the claim that the new playground increased use of the park?', '["The park is near a library", "Some parents prefer quiet parks", "More families visited the park each week after the playground opened than before", "The playground has three slides"]'::jsonb, 2, null, 'Only this finding compares park visits before and after the playground opened.', 'published', 'import', now()),
('rwl1c_020', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'In a story, the character Ana is described as kind.', null, 'Which quotation from the story best shows that Ana is kind?', '["\"Ana had a math test on Friday.\"", "\"Ana''s favorite color was purple.\"", "\"Ana noticed the new student eating alone and asked her to join their table.\"", "\"Ana walked to school with her brother.\""]'::jsonb, 2, null, 'Inviting a lonely new student to sit with her shows kindness.', 'published', 'import', now()),
('rwl1c_021', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A student claims that the amount of material the town recycles doubled between 2018 and 2023.', '{"h": ["Year", "Tons recycled"], "r": [["2018", "600"], ["2020", "850"], ["2023", "1,200"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the claim?', '["The town has a recycling center", "The town recycled 600 tons in 2018", "Recycling is important", "The town recycled 1,200 tons in 2023, up from 600 tons in 2018"]'::jsonb, 3, null, 'The claim is that recycling doubled, so the best evidence gives both years.', 'published', 'import', now()),
('rwl1c_022', 'rw', 1, 'Information and Ideas', 'Inferences', 'When Maya stepped outside in the morning, there were puddles on the sidewalk, the grass was wet, and water was dripping from the leaves. She guessed that ____', null, 'Which choice most logically completes the text?', '["the sidewalk had been painted", "the sun was very hot", "no one lived on the street", "it had probably rained during the night"]'::jsonb, 3, null, 'Puddles, wet grass, and dripping leaves are clues that it rained.', 'published', 'import', now()),
('rwl1c_023', 'rw', 1, 'Information and Ideas', 'Inferences', 'As soon as Grandma opened the gate, the dog ran toward her, wagging its tail and jumping in circles. It was clear that ____', null, 'Which choice most logically completes the text?', '["the dog was afraid of her", "the dog did not know her", "the dog wanted to sleep", "the dog was happy to see her"]'::jsonb, 3, null, 'A wagging tail and jumping excitedly suggest the dog was happy.', 'published', 'import', now()),
('rwl1c_024', 'rw', 1, 'Information and Ideas', 'Inferences', 'Jamal placed three bean plants on a sunny windowsill and three in a dark closet. He gave all six the same amount of water. After two weeks, the plants by the window were tall and green, while the ones in the closet were small and pale. Jamal concluded that ____', null, 'Which choice most logically completes the text?', '["all of the plants were the same height", "the plants near the window needed sunlight to grow well", "plants do not need light", "the plants in the closet got too much water"]'::jsonb, 1, null, 'The only difference was sunlight, and only the window plants grew well.', 'published', 'import', now()),
('rwl1c_025', 'rw', 1, 'Information and Ideas', 'Inferences', 'On the bus ride home from the science museum, the students could not stop talking about the dinosaur skeletons and the planetarium show. Several asked their teacher when they could go back. It seemed that ____', null, 'Which choice most logically completes the text?', '["the class did not go on the trip", "the class had enjoyed the field trip", "the museum was closed", "the students were bored"]'::jsonb, 1, null, 'Excited talk and eagerness to return show they enjoyed it.', 'published', 'import', now()),
('rwl1c_026', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The Nile is often called the world''s longest ____ Amazon carries the most water.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["river, the", "river and, the", "river. The", "river the"]'::jsonb, 2, null, 'These are two complete sentences, so a period separates them.', 'published', 'import', now()),
('rwl1c_027', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The orchard grows four kinds of ____ pears, peaches, and plums.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["fruits; apples,", "fruits: apples,", "fruits apples,", "fruits, apples:"]'::jsonb, 1, null, 'A colon introduces the list after a complete sentence.', 'published', 'import', now()),
('rwl1c_028', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Harriet ____ escaped from slavery in 1849, later led many others to freedom.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Tubman, who", "Tubman; who", "Tubman who", "Tubman. Who"]'::jsonb, 0, null, 'The "who" clause adds extra information about Tubman and is set off with commas.', 'published', 'import', now()),
('rwl1c_029', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The hikers were ____ they rested beside the stream before continuing up the trail.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["tired, so", "tired; so,", "tired. So,", "tired so"]'::jsonb, 0, null, 'A comma comes before "so" when it joins two complete sentences.', 'published', 'import', now()),
('rwl1c_030', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The bright red ____ soared high above the beach.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["kite:", "kite;", "kite,", "kite"]'::jsonb, 3, null, 'No punctuation belongs between the subject "The bright red kite" and its verb.', 'published', 'import', now()),
('rwl1c_031', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The library is closed on ____ it is open late on Thursday.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Monday;", "Monday,", "Monday:", "Monday"]'::jsonb, 0, null, 'A semicolon joins the two complete sentences.', 'published', 'import', now()),
('rwl1c_032', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The cookies that my uncle baked for the party ____ gone in minutes.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "was", "is", "has been"]'::jsonb, 0, null, 'The subject "the cookies" is plural, so the verb is "were."', 'published', 'import', now()),
('rwl1c_033', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The boy carefully placed ____ science project on the display table.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["its", "his", "their", "her"]'::jsonb, 1, null, 'The pronoun refers to "the boy," so "his" is correct.', 'published', 'import', now()),
('rwl1c_034', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'In 1953, Tenzing Norgay and Edmund Hillary ____ to the top of Mount Everest.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["will climb", "climbed", "is climbing", "climbs"]'::jsonb, 1, null, 'The sentence describes an event in 1953, so the past tense is needed.', 'published', 'import', now()),
('rwl1c_035', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The principal held a meeting in the ____ lounge after school.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["teachers''", "teacher''s", "teachers", "teacherses"]'::jsonb, 0, null, 'The lounge belongs to many teachers, so the plural possessive "teachers''" is correct.', 'published', 'import', now()),
('rwl1c_036', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'Each of the dogs at the shelter ____ when a visitor walks in.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["bark", "barking", "barks", "have barked"]'::jsonb, 2, null, 'The subject "Each of the dogs" is singular, so "barks" is correct.', 'published', 'import', now()),
('rwl1c_037', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'Our coach shared the good news with ____ before practice.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["we", "us", "our", "ours"]'::jsonb, 1, null, 'The pronoun is the object of "with," so "us" is correct.', 'published', 'import', now()),
('rwl1c_038', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Most snakes hatch from eggs. ____ some snakes, such as boa constrictors, give birth to live young.', null, 'Which choice completes the text with the most logical transition?', '["Similarly,", "Therefore,", "For example,", "However,"]'::jsonb, 3, null, 'The second sentence contrasts with the first (most snakes lay eggs, but some don''t).', 'published', 'import', now()),
('rwl1c_039', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Making a paper airplane is easy. ____ fold a sheet of paper in half the long way. Then fold the top corners down to the center crease.', null, 'Which choice completes the text with the most logical transition?', '["First,", "Instead,", "However,", "Finally,"]'::jsonb, 0, null, 'This begins a sequence of steps, so "First" fits.', 'published', 'import', now()),
('rwl1c_040', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Noah practiced his spelling words every evening for two weeks. ____ he spelled every word correctly on Friday''s test.', null, 'Which choice completes the text with the most logical transition?', '["For example,", "As a result,", "Meanwhile,", "However,"]'::jsonb, 1, null, 'Practicing every day led to the improvement, so a result transition fits.', 'published', 'import', now()),
('rwl1c_041', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Many animals use camouflage to hide. ____ a chameleon can change the color of its skin to match its surroundings.', null, 'Which choice completes the text with the most logical transition?', '["As a result,", "For example,", "However,", "Finally,"]'::jsonb, 1, null, 'The second sentence gives an example of an animal that uses camouflage.', 'published', 'import', now()),
('rwl1c_042', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Walking to school is good exercise. ____ it gives students time to talk with friends along the way.', null, 'Which choice completes the text with the most logical transition?', '["In contrast,", "However,", "Instead,", "Also,"]'::jsonb, 3, null, 'The second sentence adds another reason, so "Also" fits.', 'published', 'import', now()),
('rwl1c_043', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Giant pandas live in the mountains of central China.
• Their forests are cool and rainy.
• They eat mostly bamboo.
• Adults can weigh up to 300 pounds.
• Newborn pandas weigh only about 4 ounces.', null, 'The student wants to describe where giant pandas live. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["A giant panda can weigh up to 300 pounds.", "Baby pandas are born very small.", "Giant pandas eat mostly bamboo.", "Giant pandas live in cool, rainy bamboo forests in the mountains of central China."]'::jsonb, 3, null, 'Only this choice tells where pandas live.', 'published', 'import', now()),
('rwl1c_044', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Ellen Ochoa was born in California in 1958.
• She studied physics and electrical engineering.
• She plays the flute.
• In 1993, she became the first Hispanic woman to travel into space.
• She later directed NASA''s Johnson Space Center.', null, 'The student wants to explain what Ellen Ochoa is known for. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Ellen Ochoa studied physics and electrical engineering.", "In 1993, Ellen Ochoa became the first Hispanic woman to travel into space.", "Ellen Ochoa was born in California.", "Ellen Ochoa plays the flute."]'::jsonb, 1, null, 'Only this choice gives her famous achievement.', 'published', 'import', now()),
('rwl1c_045', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Frogs and toads are both amphibians.
• Both begin life as tadpoles in water.
• Frogs have smooth, wet skin and long legs.
• Toads have dry, bumpy skin and shorter legs.', null, 'The student wants to show a similarity between frogs and toads. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Both frogs and toads are amphibians that begin life as tadpoles in water.", "Toads have dry, bumpy skin.", "Frogs have longer legs than toads.", "Frogs have smooth, wet skin."]'::jsonb, 0, null, 'Only this choice states something they share.', 'published', 'import', now())
